$sourceFiles=@($source,(Join-Path $repo 'tests\native\coarse_pv_transfer_selftest.cpp'),(Join-Path $repo 'tests\native\wmma_pv_operands_selftest.cpp'),(Join-Path $repo 'native\providers\sm121_attention_capacity.h'))
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName})
}
$sourceInputs=@($sourceFiles|Sort-Object -Unique|ForEach-Object {@{file=$_;sha256=(Get-FileHash $_ -Algorithm SHA256).Hash.ToLowerInvariant()}})
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; isolated register PV arithmetic and row reciprocals';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false;purpose='Compare original PV, an otherwise equivalent copied control, explicit register FP32 rescale barriers, and register rescale plus one original table-derived reciprocal per query/head. The original K16 recurrence, native error envelope, complete candidate membership and exact replay are unchanged. A1048576-pair native comparison checks the multiply barrier. Generated cases and captures check every native pre-replay raw center/output/denominator/error surface, complete corrected raw surfaces, independent CPU reciprocal values, original candidate masks, guards and input immutability. Captured clocks include all arithmetic, optional reciprocal preparation, counter initialization, collection and complete original replay. No model-token or TTFT acceptance.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action.StartsWith('build')){
 $link=Join-Path $build 'hipblaslt.lib';Copy-Item 'C:\Program Files\AMD\ROCm\7.1\lib\libhipblaslt.dll.a' $link
 $spec.link_inputs=@(@{file=$link;sha256=(Get-FileHash $link -Algorithm SHA256).Hash.ToLowerInvariant()})
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','-DQRT_CK_SM121_INTERPOLATED_EXP2=1','--offload-arch=gfx1151','-L',$build,$source,'-o',$exe,'-lhipblaslt');$timeout=240
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $exe $meta.executable.sha256
 foreach($file in $meta.source_inputs){Verify-File $file.file $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
 $exp='D:\projects\sm121-exp2-interpolated-b5752a88.bin';$rcp='D:\projects\sm121-attention-rcp-d2e55754.bin'
 $tables=@(@{file=$exp;sha256='b5752a88488d8e6382cc99a897ef822e97758e0a782930c174954a5299126eec'},@{file=$rcp;sha256='d2e557543f6bc51f5141ba6414000cd8ed892e2e915eda19245c3cae22c16b39'})
 foreach($file in $tables){Verify-File $file.file $file.sha256}
 $spec.input_files=$tables;$spec.executable=$exe;$spec.arguments=@('--selftest',$exp,$rcp);$timeout=300
 if($Action -eq 'q7169' -or $Action -eq 'q8192'){
  $safety=Join-Path $repo 'build\register-pv-test-r1\run-record.json';$sr=[IO.File]::ReadAllText($safety)|ConvertFrom-Json;if($sr.reason -ne 'completed' -or $sr.exit_code -ne 0 -or -not $sr.host_checks_pass){throw 'Native safety prerequisite failed'};$spec.native_safety_sha256=(Get-FileHash $safety -Algorithm SHA256).Hash.ToLowerInvariant()
  $capRoot='D:\projects\AIMA-public-fa-out-20260911\build\fla-model-q7169-fa-out-r1'
  $q=Join-Path $capRoot 'layer3-full-full_attention_q_norm_rope-bf16.bin';$k=Join-Path $capRoot 'layer3-full-full_attention_k_norm_rope-bf16.bin'
  $v=Join-Path $capRoot 'layer3-full-full_attention_v_projection-bf16.bin';$ref='D:\projects\full-attention-context-gb10-08734309.bin'
  $inputs=@(@{file=$q;sha256='c04de09df4879842e299db9822c76e0b6e13a70c345cb9803d74722e25f24b7d'},@{file=$k;sha256='99bd880e732fd2786c12a68113fe5f834b5cc0fe87b09b0aaf5734c90bf3f2e8'},@{file=$v;sha256='bd95f94c94ea0606c94b6d98548a672e78479bf6df2d7ace08f3797a85907e80'},@{file=$ref;sha256='f3d9b30a1e70f97a5510a0242006e91e0754207bb8e437cdf46d777bfb6fed33'})+$tables
  foreach($file in $inputs){Verify-File $file.file $file.sha256}
  $spec.input_files=$inputs;$spec.arguments=@(('--'+$Action),$q,$k,$v,$ref,$exp,$rcp)
  $spec.model='D:\models\Qwen3.6-35B-A3B; original captured q7169 layer3 QKV; q8192 repeats the first1023 captured rows as a component extension'
  $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83';$spec.input_run_sha256='4a4334d65056371866a10626bec395f9778a2cb6a182ead0560c35ea5cb20146';$spec.input_whole_source='28c4f9df501e8e95ac357acc45d30daf48633bf8'
  $spec.gb10_reference_capture_sha256='087343091048d50a12977548a24a6f2a0fd3346352bceb42fb160c3cf6a6bd37';$spec.external_unique_bf16_cells=29364224
  $spec.real_model_prompt=$false;$spec.reference_is_compute_input=$false
 }

}
$out=Join-Path $repo ('build\register-pv-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(2000,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic action failed'}
if($Action.StartsWith('build')){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;link_inputs=$spec.link_inputs;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $round=@($reports|Where-Object {$_.kind -eq 'register_pv_rounding'})
 if($round.Count -ne 1 -or $round[0].comparisons -ne 1048576 -or $round[0].raw_mismatches -ne 0){throw 'Multiply barrier comparison failed'}
 $values=@($reports|Where-Object {$_.kind -ne 'register_pv_rounding'})
 $expected=if($Action -eq 'test'){252}else{4}
 if($values.Count -ne $expected){throw 'Incomplete register PV reports'}
 foreach($r in $values){if($r.raw_bit_mismatches -ne 0 -or $r.bf16_mismatches -ne 0 -or -not $r.native_pre_replay_raw_parity -or -not $r.complete_original_membership -or -not $r.cpu_reciprocal_parity -or -not $r.redzones_and_unused_tails_pass -or -not $r.immutable_inputs){throw 'Register PV numerical or memory comparison failed'}}
 foreach($file in $spec.input_files){Verify-File $file.file $file.sha256}
}

