$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$psi=[Diagnostics.ProcessStartInfo]::new('C:\Program Files\AMD\ROCm\7.1\bin\llvm-objdump.exe')
$psi.Arguments='-d --mcpu=gfx1151 D:\projects\register-pv-isa-20260917-r1.hsaco';$psi.UseShellExecute=$false
$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
$proc=[Diagnostics.Process]::new();$proc.StartInfo=$psi
if(-not $proc.Start()){throw 'ISA process did not start'}
$stdout=$proc.StandardOutput.ReadToEndAsync();$stderr=$proc.StandardError.ReadToEndAsync()
if(-not $proc.WaitForExit(20000)){& taskkill.exe /PID $proc.Id /T /F|Out-Null;throw 'ISA tool timed out'}
$proc.WaitForExit()
[IO.File]::WriteAllText('D:\projects\register-pv-isa-20260917-r1-isa.txt',$stdout.Result,[Text.UTF8Encoding]::new($false))
if($proc.ExitCode -ne 0){throw ('ISA failed '+$stderr.Result)}
